INSERT INTO public.words (id, deck_id, language, term, pronunciation, meaning, example_sentence, example_translation, accepted_answers, order_index, archived) VALUES
('b0a13557-1847-5687-a453-6866487c03a7', '07d7c839-1a05-5a71-a126-5769eb7e0e24', 'zh', '启示', 'qǐshì', 'sự khai sáng, sự gợi ý', '', '', ARRAY['启示']::text[], 0, false),
('fdbfe8f6-e699-5fa0-a485-59f5952cb8ae', '07d7c839-1a05-5a71-a126-5769eb7e0e24', 'zh', '老公', 'lǎogōng', 'chồng', '天天的父母要出差，想请我们帮忙照看今天女儿，我和老公爽快地答应下来，有个孩子和我们的独生女朝夕相处，我们巴不得呢！', '', ARRAY['老公']::text[], 1, false),
('e8431466-7849-585a-a581-12dffad00513', '07d7c839-1a05-5a71-a126-5769eb7e0e24', 'zh', '爽快', 'shǎngkuai', 'thẳng thắng, sảng khoái', '天天的父母要出差，想请我们帮忙照看今天女儿，我和老公爽快地答应下来，有个孩子和我们的独生女朝夕相处，我们巴不得呢！', '', ARRAY['爽快']::text[], 2, false),
('f708a722-32cd-5525-a975-cd628388007a', '07d7c839-1a05-5a71-a126-5769eb7e0e24', 'zh', '巴不得', 'bābudé', 'chỉ mong sao, ước ao', '天天的父母要出差，想请我们帮忙照看今天女儿，我和老公爽快地答应下来，有个孩子和我们的独生女朝夕相处，我们巴不得呢！', '', ARRAY['巴不得']::text[], 3, false),
('bf0418e3-e47a-57d2-a28a-33e047f28906', '07d7c839-1a05-5a71-a126-5769eb7e0e24', 'zh', '嚷', 'rǎng', 'la hét, kêu gào', '最兴奋的是林林，嚷着要用爸爸最拿手的美味佳肴欢迎天天来我家，还提出，她的书桌可以和天天共用。', '', ARRAY['嚷']::text[], 4, false),
('5556132d-24c0-5c6e-ae52-8918b690685e', '07d7c839-1a05-5a71-a126-5769eb7e0e24', 'zh', '拿手', 'náshǒu', 'tài ba, giỏi, thành thạo', '最兴奋的是林林，嚷着要用爸爸最拿手的美味佳肴欢迎天天来我家，还提出，她的书桌可以和天天共用。', '', ARRAY['拿手']::text[], 5, false),
('5c46137a-f696-510c-a8e6-4eac2fa3af36', '07d7c839-1a05-5a71-a126-5769eb7e0e24', 'zh', '佳肴', 'jiāyáo', 'món ngon', '最兴奋的是林林，嚷着要用爸爸最拿手的美味佳肴欢迎天天来我家，还提出，她的书桌可以和天天共用。', '', ARRAY['佳肴']::text[], 6, false),
('50e9182b-4f4c-55bd-ae4c-7c9e169be88b', '07d7c839-1a05-5a71-a126-5769eb7e0e24', 'zh', '异常', 'yìcháng', 'đặc biệt, cực kỳ', '天天还没来，林林就变得异常勤劳，将屋子收拾得干干净净，东西摆放得整整齐齐，什么好事都想着天天。', '', ARRAY['异常']::text[], 7, false),
('c42fbfcf-ce64-5edd-aec4-5d4e3c97d347', '07d7c839-1a05-5a71-a126-5769eb7e0e24', 'zh', '勤劳', 'qínláo', 'siêng năng, cần cù', '天天还没来，林林就变得异常勤劳，将屋子收拾得干干净净，东西摆放得整整齐齐，什么好事都想着天天。', '', ARRAY['勤劳']::text[], 8, false),
('a2277262-10bd-5e91-a8ef-84eeaccdfad2', '07d7c839-1a05-5a71-a126-5769eb7e0e24', 'zh', '绅士', 'shēnshì', 'người lịch thiệp', '我家林林虽是女孩，却也绅士风度十足。', '', ARRAY['绅士']::text[], 9, false),
('6b987255-b23f-51bd-acdc-bf8ab92d93bd', '07d7c839-1a05-5a71-a126-5769eb7e0e24', 'zh', '风度', 'fēngdù', 'phong độ', '我家林林虽是女孩，却也绅士风度十足。', '', ARRAY['风度']::text[], 10, false),
('fec553cd-1b0a-5616-a9a2-56ff9d1978b2', '07d7c839-1a05-5a71-a126-5769eb7e0e24', 'zh', '十足', 'shízú', 'tràn đầy, đầy đủ', '我家林林虽是女孩，却也绅士风度十足。', '', ARRAY['十足']::text[], 11, false),
('e8c954fb-e952-5036-ad18-8495dc363b63', '07d7c839-1a05-5a71-a126-5769eb7e0e24', 'zh', '督促', 'dūcù', 'thúc giục, hối thúc', '两个孩子天天早上不用叫就醒了，上学不用接送，做作业不用督促；', '', ARRAY['督促']::text[], 12, false),
('c811b99e-7244-5a79-a254-5451007e4fcc', '07d7c839-1a05-5a71-a126-5769eb7e0e24', 'zh', '打架', 'dǎ jià', 'đánh nhau', '她们不打架，不闹别扭，关系别提多融洽了。', '', ARRAY['打架']::text[], 13, false),
('b431dd20-a5e3-5a90-a604-d3e9f6cdde65', '07d7c839-1a05-5a71-a126-5769eb7e0e24', 'zh', '别扭', 'bièniù', 'có xích mích, không hợp', '她们不打架，不闹别扭，关系别提多融洽了。', '', ARRAY['别扭']::text[], 14, false),
('2f74a195-7ce1-5996-a7c5-26856a7f1f3b', '07d7c839-1a05-5a71-a126-5769eb7e0e24', 'zh', '融洽', 'róngqià', 'hoà hợp, hoà thuận', '她们不打架，不闹别扭，关系别提多融洽了。', '', ARRAY['融洽']::text[], 15, false),
